    private static final class CheckCellRenderer extends JComponent implements javax.swing.table.TableCellRenderer{private boolean checked;public Component getTableCellRendererComponent(JTable t,Object v,boolean s,boolean f,int r,int c){checked=Boolean.TRUE.equals(v);return this;}protected void paintComponent(Graphics g){Graphics2D g2=(Graphics2D)g.create();g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int x=(getWidth()-16)/2,y=(getHeight()-16)/2;g2.setColor(checked?ACCENT:UIManager.getColor("Component.borderColor"));if(checked)g2.fillRoundRect(x,y,16,16,6,6);else g2.drawRoundRect(x,y,15,15,6,6);if(checked){g2.setColor(Color.WHITE);g2.setStroke(new BasicStroke(2f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g2.drawLine(x+4,y+8,x+7,y+11);g2.drawLine(x+7,y+11,x+12,y+5);}g2.dispose();}}
    private static final class RoundedTable extends JTable{RoundedTable(AbstractTableModel model){super(model);setOpaque(false);ToolTipManager.sharedInstance().registerComponent(this);}public String getToolTipText(java.awt.event.MouseEvent e){int row=rowAtPoint(e.getPoint()),col=columnAtPoint(e.getPoint());if(row<0||col<=0)return null;Object value=getValueAt(row,col);return value==null||value.toString().isBlank()?null:value.toString();}protected void paintComponent(Graphics g){Graphics2D g2=(Graphics2D)g.create();g2.setColor(UIManager.getColor("Table.background"));g2.fillRect(0,0,getWidth(),getHeight());int row=getSelectedRow();if(row>=0){Rectangle r=getCellRect(row,0,true);r.width=getWidth();g2.setColor(UIManager.getColor("Table.selectionBackground"));g2.fillRoundRect(r.x+3,r.y+2,r.width-6,r.height-4,14,14);}g2.dispose();super.paintComponent(g);}}
    private static final class RoundedScrollPane extends JScrollPane{RoundedScrollPane(Component view){super(view);setOpaque(false);}public void paint(Graphics g){Graphics2D g2=(Graphics2D)g.create();g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g2.clip(new java.awt.geom.RoundRectangle2D.Float(0,0,getWidth(),getHeight(),14,14));g2.setColor(viewport.getView() instanceof JTextArea?UIManager.getColor("TextArea.background"):UIManager.getColor("Panel.background"));g2.fillRect(0,0,getWidth(),getHeight());super.paint(g2);g2.dispose();}}
    private static JComponent songHeader(){return new JPanel(new GridBagLayout()){ {setOpaque(false);String[] names={"","标题","艺术家","专辑"};for(int i=0;i<4;i++){GridBagConstraints c=new GridBagConstraints();c.gridy=0;c.gridx=i;c.fill=GridBagConstraints.BOTH;c.weighty=1;c.weightx=i==0?0:1;JLabel label=new JLabel(names[i],SwingConstants.CENTER);add(label,c);if(i==0)label.setPreferredSize(new Dimension(30,38));}} protected void paintComponent(Graphics g){Graphics2D g2=(Graphics2D)g.create();g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g2.setColor(UIManager.getColor("TableHeader.background"));g2.fillRoundRect(0,0,getWidth(),getHeight(),14,14);g2.dispose();super.paintComponent(g);} public Dimension getPreferredSize(){return new Dimension(0,38);}};}
    private static final class CoverView extends JComponent{private Image image;CoverView(){setOpaque(false);}void setCover(byte[] bytes){image=bytes==null?null:new ImageIcon(bytes).getImage();repaint();}protected void paintComponent(Graphics g){Graphics2D g2=(Graphics2D)g.create();g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);java.awt.Shape shape=new java.awt.geom.RoundRectangle2D.Float(1,1,getWidth()-2,getHeight()-2,16,16);g2.clip(shape);if(image==null){g2.setColor(UIManager.getColor("TextField.background"));g2.fill(shape);g2.setClip(null);g2.setColor(UIManager.getColor("Label.disabledForeground"));String text="无封面";FontMetrics fm=g2.getFontMetrics();g2.drawString(text,(getWidth()-fm.stringWidth(text))/2,(getHeight()+fm.getAscent())/2);}else{g2.drawImage(image,1,1,getWidth()-2,getHeight()-2,null);}g2.setClip(null);g2.setColor(dark?new Color(72,72,72):new Color(205,208,214));g2.drawRoundRect(1,1,getWidth()-3,getHeight()-3,16,16);g2.dispose();}}
    private static final class RatioLayout implements LayoutManager{private final int gap;RatioLayout(int gap){this.gap=gap;}public void addLayoutComponent(String n,Component c){}public void removeLayoutComponent(Component c){}public Dimension preferredLayoutSize(Container p){return new Dimension(1000,600);}public Dimension minimumLayoutSize(Container p){return new Dimension(0,0);}public void layoutContainer(Container p){if(p.getComponentCount()<3)return;Insets i=p.getInsets();int width=p.getWidth()-i.left-i.right-gap*2,height=p.getHeight()-i.top-i.bottom;int first=(int)(width*.30),second=(int)(width*.30),third=width-first-second;p.getComponent(0).setBounds(i.left,i.top,first,height);p.getComponent(1).setBounds(i.left+first+gap,i.top,second,height);p.getComponent(2).setBounds(i.left+first+gap+second+gap,i.top,third,height);}}
