    private static final class RoundedBorder extends AbstractBorder {private final Color color;private final int arc;RoundedBorder(Color c,int a){color=c;arc=a;}public void paintBorder(Component c,Graphics g,int x,int y,int w,int h){Graphics2D g2=(Graphics2D)g.create();g2.setColor(dark?new Color(72,72,72):color);g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g2.drawRoundRect(x,y,w-1,h-1,arc,arc);g2.dispose();}public Insets getBorderInsets(Component c){return new Insets(5,7,5,7);}}
    private static final class SongModel extends AbstractTableModel {final List<AudioTagData> items=new ArrayList<>();final List<Boolean> checked=new ArrayList<>();void add(AudioTagData d){int r=items.size();items.add(d);checked.add(true);fireTableRowsInserted(r,r);}void clear(){int size=items.size();items.clear();checked.clear();if(size>0)fireTableRowsDeleted(0,size-1);}void selectAll(boolean v){for(int i=0;i<checked.size();i++)checked.set(i,v);fireTableDataChanged();}List<Integer> checkedRows(){List<Integer> r=new ArrayList<>();for(int i=0;i<checked.size();i++)if(checked.get(i))r.add(i);return r;}public int getRowCount(){return items.size();}public int getColumnCount(){return 4;}public String getColumnName(int c){return new String[]{"","标题","艺术家","专辑"}[c];}public Class<?> getColumnClass(int c){return c==0?Boolean.class:String.class;}public boolean isCellEditable(int r,int c){return false;}public Object getValueAt(int r,int c){AudioTagData d=items.get(r);return switch(c){case 0->checked.get(r);case 1->d.displayName();case 2->d.artist();default->d.album();};}public void setValueAt(Object v,int r,int c){if(c==0){checked.set(r,(Boolean)v);fireTableCellUpdated(r,c);}}}
